input.script:
first = boundary retry 2 {
    return list_tickets({ page: 1, status: "open" })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, first.total_pages + 1) {
    result = boundary retry 2 { return list_tickets({ page, status: "open" }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
listing = fold acc = first.items for page in remaining { return acc + page }
cutoff = time.parse("2026-06-10T00:00:00Z") - 7 * 86400000
matches = for record in listing {
    detail = boundary retry 2 {
        return get_ticket({ id: record.id })
    } catch err {
        return fail("GET_FAILED", err.code + ": " + err.message)
    }
    old = time.parse(detail.created_at) < cutoff
    refund = "refund" in text.lower(detail.body)
    skip if not (old and refund)
    upd = boundary retry 2 {
        return update_ticket({ id: record.id, priority: "high", add_tags: ["billing-escalation"] })
    } catch err {
        return fail("UPDATE_FAILED", err.code + ": " + err.message)
    }
    return record.id
}
submitted = submit_result({ answer: { escalated_ticket_ids: matches } })
return { escalated: matches, submitted }
